package org.kinotic.persistence.internal.api.services.json.hooks.impl;

import org.kinotic.domain.api.model.persistence.idl.decorators.AutoGeneratedIdDecorator;
import org.kinotic.persistence.internal.api.services.json.hooks.EntityUpsertState;
import org.kinotic.persistence.internal.api.services.json.hooks.UpsertFieldTransformer;
import org.springframework.stereotype.Component;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.JsonParser;

import java.util.UUID;

/**
 * Fills a null or blank {@link AutoGeneratedIdDecorator} field with a random UUID, keeps an id that is given, and
 * records the result as the entity's id.
 * Created by Navíd Mitchell 🤪 on 5/9/23.
 */
@Component
public class AutoGeneratedIdUpsertFieldTransformer implements UpsertFieldTransformer {

    @Override
    public Class<AutoGeneratedIdDecorator> implementsDecorator() {
        return AutoGeneratedIdDecorator.class;
    }

    @Override
    public void transform(JsonParser parser, JsonGenerator generator, EntityUpsertState state) {
        String fieldName = parser.currentName();
        String given = state.readFieldValue(parser, String.class);
        String id = given != null && !given.isBlank() ? given : UUID.randomUUID().toString();

        generator.writeStringProperty(fieldName, id);

        if(state.isRootField()){
            state.recordId(id);
        }
    }
}
